58	typedef struct {
59	    int64_t beg, end;
60	    char *ss, *se;
61	    int tid;
62	} tbx_intv_t;
63	
64	static inline int get_tid(tbx_t *tbx, const char *ss, int is_add)
65	{
66	    khint_t k;
67	    khash_t(s2i) *d;
68	    if ((tbx->conf.preset&0xffff) == TBX_GAF) return(0);
69	    if (tbx->dict == 0) tbx->dict = kh_init(s2i);
70	    if (!tbx->dict) return -1; // Out of memory
71	    d = (khash_t(s2i)*)tbx->dict;
72	    if (is_add) {
73	        int absent;
74	        k = kh_put(s2i, d, ss, &absent);
75	        if (absent < 0) {
76	            return -1; // Out of memory
77	        } else if (absent) {
78	            char *ss_dup = strdup(ss);
79	            if (ss_dup) {
80	                kh_key(d, k) = ss_dup;
81	                kh_val(d, k) = kh_size(d) - 1;
82	            } else {
83	                kh_del(s2i, d, k);
84	                return -1; // Out of memory
85	            }
86	        }
87	    } else k = kh_get(s2i, d, ss);
88	    return k == kh_end(d)? -1 : kh_val(d, k);
89	}
