96	int tbx_parse1(const tbx_conf_t *conf, size_t len, char *line, tbx_intv_t *intv)
97	{
98	    size_t i, b = 0;
99	    int id = 1;
100	    char *s;
101	    intv->ss = intv->se = 0; intv->beg = intv->end = -1;
102	    for (i = 0; i <= len; ++i) {
103	        if (line[i] == '\t' || line[i] == 0) {
104	            if (id == conf->sc) {
105	                intv->ss = line + b; intv->se = line + i;
106	            } else if (id == conf->bc) {
107	                // here ->beg is 0-based.
108	                if ((conf->preset&0xffff) == TBX_GAF){
109	                    // if gaf find the smallest and largest node id
110	                    char *t;
111	                    int64_t nodeid = -1;
112	                    for (s = line + b + 1; s < line + i;) {
113	                        nodeid = strtoll(s, &t, 0);
114	                        if(intv->beg == -1){
115	                            intv->beg = intv->end = nodeid;
116	                        } else {
117	                            if(nodeid < intv->beg){
118	                                intv->beg = nodeid;
119	                            }
120	
121	                            if(nodeid > intv->end){
122	                                intv->end = nodeid;
123	                            }
124	                        }
125	                        s = t + 1;
126	                    }
127	                } else {
128	                    intv->beg = strtoll(line + b, &s, 0);
129	
130	                    if (conf->bc <= conf->ec) // don't overwrite an already set end point
131	                        intv->end = intv->beg;
132	
133	                    if ( s==line+b ) return -1; // expected int
134	
135	                    if (!(conf->preset&TBX_UCSC))
136	                        --intv->beg;
137	                    else if (conf->bc <= conf->ec)
138	                        ++intv->end;
139	
140	                    if (intv->beg < 0) {
141	                        hts_log_warning("Coordinate <= 0 detected. "
142	                                        "Did you forget to use the -0 option?");
143	                        intv->beg = 0;
144	                    }
145	                    if (intv->end < 1) intv->end = 1;
146	                }
147	            } else {
148	                if ((conf->preset&0xffff) == TBX_GENERIC) {
149	                    if (id == conf->ec)
150	                    {
151	                        intv->end = strtoll(line + b, &s, 0);
152	                        if ( s==line+b ) return -1; // expected int
153	                    }
154	                } else if ((conf->preset&0xffff) == TBX_SAM) {
155	                    if (id == 6) { // CIGAR
156	                        int l = 0;
157	                        char *t;
158	                        for (s = line + b; s < line + i;) {
159	                            long x = strtol(s, &t, 10);
160	                            char op = toupper_c(*t);
161	                            if (op == 'M' || op == 'D' || op == 'N') l += x;
162	                            s = t + 1;
163	                        }
164	                        if (l == 0) l = 1;
165	                        intv->end = intv->beg + l;
166	                    }
167	                } else if ((conf->preset&0xffff) == TBX_VCF) {
168	                    if (id == 4) {
169	                        if (b < i) intv->end = intv->beg + (i - b);
170	                    } else if (id == 8) { // look for "END="
171	                        int c = line[i];
172	                        line[i] = 0;
173	                        s = strstr(line + b, "END=");
174	                        if (s == line + b) s += 4;
175	                        else if (s) {
176	                            s = strstr(line + b, ";END=");
177	                            if (s) s += 5;
178	                        }
179	                        if (s && *s != '.') {
180	                            long long end = strtoll(s, &s, 0);
181	                            if (end <= intv->beg) {
182	                                static int reported = 0;
183	                                if (!reported) {
184	                                    int l = intv->ss ? (int) (intv->se - intv->ss) : 0;
185	                                    hts_log_warning("VCF INFO/END=%lld is smaller than POS at %.*s:%"PRIhts_pos"\n"
186	                                                    "This tag will be ignored. "
187	                                                    "Note: only one invalid END tag will be reported.",
188	                                                    end, l >= 0 ? l : 0,
189	                                                    intv->ss ? intv->ss : "",
190	                                                    intv->beg);
191	                                    reported = 1;
192	                                }
193	                            } else {
194	                                intv->end = end;
195	                            }
196	                        }
197	                        line[i] = c;
198	                    }
199	                }
200	            }
201	            b = i + 1;
202	            ++id;
203	        }
204	    }
205	    if (intv->ss == 0 || intv->se == 0 || intv->beg < 0 || intv->end < 0) return -1;
206	    return 0;
207	}
