209	static inline int get_intv(tbx_t *tbx, kstring_t *str, tbx_intv_t *intv, int is_add)
210	{
211	    if (tbx_parse1(&tbx->conf, str->l, str->s, intv) == 0) {
212	        int c = *intv->se;
213	        *intv->se = '\0';
214	        if ((tbx->conf.preset&0xffff) == TBX_GAF){
215	            intv->tid = 0;
216	        } else {
217	            intv->tid = get_tid(tbx, intv->ss, is_add);
218	        }
219	        *intv->se = c;
220	        if (intv->tid < 0) return -2;  // get_tid out of memory
221	        return (intv->beg >= 0 && intv->end >= 0)? 0 : -1;
222	    } else {
223	        char *type = NULL;
224	        switch (tbx->conf.preset&0xffff)
225	        {
226	            case TBX_SAM: type = "TBX_SAM"; break;
227	            case TBX_VCF: type = "TBX_VCF"; break;
228	            case TBX_GAF: type = "TBX_GAF"; break;
229	            case TBX_UCSC: type = "TBX_UCSC"; break;
230	            default: type = "TBX_GENERIC"; break;
231	        }
232	        if (hts_is_utf16_text(str))
233	            hts_log_error("Failed to parse %s: offending line appears to be encoded as UTF-16", type);
234	        else
235	            hts_log_error("Failed to parse %s: was wrong -p [type] used?\nThe offending line was: \"%s\"",
236	                type, str->s);
237	        return -1;
238	    }
239	}
