241	/*
242	 * Called by tabix iterator to read the next record.
243	 * Returns    >=  0 on success
244	 *               -1 on EOF
245	 *            <= -2 on error
246	 */
247	int tbx_readrec(BGZF *fp, void *tbxv, void *sv, int *tid, hts_pos_t *beg, hts_pos_t *end)
248	{
249	    tbx_t *tbx = (tbx_t *) tbxv;
250	    kstring_t *s = (kstring_t *) sv;
251	    int ret;
252	    if ((ret = bgzf_getline(fp, '\n', s)) >= 0) {
253	        tbx_intv_t intv;
254	        if (get_intv(tbx, s, &intv, 0) < 0)
255	            return -2;
256	        *tid = intv.tid; *beg = intv.beg; *end = intv.end;
257	    }
258	    return ret;
259	}
