261	static int tbx_set_meta(tbx_t *tbx)
262	{
263	    int i, l = 0, l_nm;
264	    uint32_t x[7];
265	    char **name;
266	    uint8_t *meta;
267	    khint_t k;
268	    khash_t(s2i) *d = (khash_t(s2i)*)tbx->dict;
269	
270	    memcpy(x, &tbx->conf, 24);
271	    name = (char**)malloc(sizeof(char*) * kh_size(d));
272	    if (!name) return -1;
273	    for (k = kh_begin(d), l = 0; k != kh_end(d); ++k) {
274	        if (!kh_exist(d, k)) continue;
275	        name[kh_val(d, k)] = (char*)kh_key(d, k);
276	        l += strlen(kh_key(d, k)) + 1; // +1 to include '\0'
277	    }
278	    l_nm = x[6] = l;
279	    meta = (uint8_t*)malloc(l_nm + 28);
280	    if (!meta) { free(name); return -1; }
281	    if (ed_is_big())
282	        for (i = 0; i < 7; ++i)
283	            x[i] = ed_swap_4(x[i]);
284	    memcpy(meta, x, 28);
285	    for (l = 28, i = 0; i < (int)kh_size(d); ++i) {
286	        int x = strlen(name[i]) + 1;
287	        memcpy(meta + l, name[i], x);
288	        l += x;
289	    }
290	    free(name);
291	    hts_idx_set_meta(tbx->idx, l, meta, 0);
292	    return 0;
293	}
