295	// Minimal effort parser to extract reference length out of VCF header line
296	// This is used only used to adjust the number of levels if necessary,
297	// so not a major problem if it doesn't always work.
298	static void adjust_max_ref_len_vcf(const char *str, int64_t *max_ref_len)
299	{
300	    const char *ptr;
301	    int64_t len;
302	    if (strncmp(str, "##contig", 8) != 0) return;
303	    ptr = strstr(str + 8, "length");
304	    if (!ptr) return;
305	    for (ptr += 6; *ptr == ' ' || *ptr == '='; ptr++) {}
306	    len = strtoll(ptr, NULL, 10);
307	    if (*max_ref_len < len) *max_ref_len = len;
308	}
309	
310	// Same for sam files
311	static void adjust_max_ref_len_sam(const char *str, int64_t *max_ref_len)
312	{
313	    const char *ptr;
314	    int64_t len;
315	    if (strncmp(str, "@SQ", 3) != 0) return;
316	    ptr = strstr(str + 3, "\tLN:");
317	    if (!ptr) return;
318	    ptr += 4;
319	    len = strtoll(ptr, NULL, 10);
320	    if (*max_ref_len < len) *max_ref_len = len;
321	}
