323	// Adjusts number of levels if not big enough.  This can happen for
324	// files with very large contigs.
325	static int adjust_n_lvls(int min_shift, int n_lvls, int64_t max_len)
326	{
327	    int64_t s = hts_bin_maxpos(min_shift, n_lvls);
328	    max_len += 256;
329	    for (; max_len > s; ++n_lvls, s <<= 3) {}
330	    return n_lvls;
331	}
