333	tbx_t *tbx_index(BGZF *fp, int min_shift, const tbx_conf_t *conf)
334	{
335	    tbx_t *tbx;
336	    kstring_t str;
337	    int ret, first = 0, n_lvls, fmt;
338	    int64_t lineno = 0;
339	    uint64_t last_off = 0;
340	    tbx_intv_t intv;
341	    int64_t max_ref_len = 0;
342	
343	    str.s = 0; str.l = str.m = 0;
344	    tbx = (tbx_t*)calloc(1, sizeof(tbx_t));
345	    if (!tbx) return NULL;
346	    tbx->conf = *conf;
347	    if (min_shift > 0) n_lvls = (TBX_MAX_SHIFT - min_shift + 2) / 3, fmt = HTS_FMT_CSI;
348	    else min_shift = 14, n_lvls = 5, fmt = HTS_FMT_TBI;
349	    while ((ret = bgzf_getline(fp, '\n', &str)) >= 0) {
350	        ++lineno;
351	        if (str.s[0] == tbx->conf.meta_char && fmt == HTS_FMT_CSI) {
352	            switch (tbx->conf.preset) {
353	                case TBX_SAM:
354	                    adjust_max_ref_len_sam(str.s, &max_ref_len); break;
355	                case TBX_VCF:
356	                    adjust_max_ref_len_vcf(str.s, &max_ref_len); break;
357	                default:
358	                    break;
359	            }
360	        }
361	        if (lineno <= tbx->conf.line_skip || str.s[0] == tbx->conf.meta_char) {
362	            last_off = bgzf_tell(fp);
363	            continue;
364	        }
365	        if (first == 0) {
366	            if (fmt == HTS_FMT_CSI) {
367	                if (!max_ref_len)
368	                    max_ref_len = (int64_t)100*1024*1024*1024; // 100G default
369	                n_lvls = adjust_n_lvls(min_shift, n_lvls, max_ref_len);
370	            }
371	            tbx->idx = hts_idx_init(0, fmt, last_off, min_shift, n_lvls);
372	            if (!tbx->idx) goto fail;
373	            first = 1;
374	        }
375	        ret = get_intv(tbx, &str, &intv, 1);
376	        if (ret < 0) goto fail;  // Out of memory or unparsable lines
377	        if (hts_idx_push(tbx->idx, intv.tid, intv.beg, intv.end,
378	                         bgzf_tell(fp), 1) < 0) {
379	            goto fail;
380	        }
381	    }
382	    if (ret < -1) goto fail;
383	    if ( !tbx->idx ) tbx->idx = hts_idx_init(0, fmt, last_off, min_shift, n_lvls);   // empty file
384	    if (!tbx->idx) goto fail;
385	    if ( !tbx->dict ) tbx->dict = kh_init(s2i);
386	    if (!tbx->dict) goto fail;
387	    if (hts_idx_finish(tbx->idx, bgzf_tell(fp)) != 0) goto fail;
388	    if (tbx_set_meta(tbx) != 0) goto fail;
389	    free(str.s);
390	    return tbx;
391	
392	 fail:
393	    free(str.s);
394	    tbx_destroy(tbx);
395	    return NULL;
396	}
397	
398	void tbx_destroy(tbx_t *tbx)
399	{
400	    khash_t(s2i) *d = (khash_t(s2i)*)tbx->dict;
401	    if (d != NULL)
402	    {
403	        khint_t k;
404	        for (k = kh_begin(d); k != kh_end(d); ++k)
405	            if (kh_exist(d, k)) free((char*)kh_key(d, k));
406	    }
407	    hts_idx_destroy(tbx->idx);
408	    kh_destroy(s2i, d);
409	    free(tbx);
410	}
