412	int tbx_index_build3(const char *fn, const char *fnidx, int min_shift, int n_threads, const tbx_conf_t *conf)
413	{
414	    tbx_t *tbx;
415	    BGZF *fp;
416	    int ret;
417	    if ((fp = bgzf_open(fn, "r")) == 0) return -1;
418	    if ( n_threads ) bgzf_mt(fp, n_threads, 256);
419	    if ( bgzf_compression(fp) != bgzf ) { bgzf_close(fp); return -2; }
420	    tbx = tbx_index(fp, min_shift, conf);
421	    bgzf_close(fp);
422	    if ( !tbx ) return -1;
423	    ret = hts_idx_save_as(tbx->idx, fn, fnidx, min_shift > 0? HTS_FMT_CSI : HTS_FMT_TBI);
424	    tbx_destroy(tbx);
425	    return ret;
426	}
