438	static tbx_t *index_load(const char *fn, const char *fnidx, int flags)
439	{
440	    tbx_t *tbx;
441	    uint8_t *meta;
442	    char *nm, *p;
443	    uint32_t l_meta, l_nm;
444	    tbx = (tbx_t*)calloc(1, sizeof(tbx_t));
445	    if (!tbx)
446	        return NULL;
447	    tbx->idx = hts_idx_load3(fn, fnidx, HTS_FMT_TBI, flags);
448	    if ( !tbx->idx )
449	    {
450	        free(tbx);
451	        return NULL;
452	    }
453	    meta = hts_idx_get_meta(tbx->idx, &l_meta);
454	    if ( !meta || l_meta < 28) goto invalid;
455	
456	    tbx->conf.preset = le_to_i32(&meta[0]);
457	    tbx->conf.sc = le_to_i32(&meta[4]);
458	    tbx->conf.bc = le_to_i32(&meta[8]);
459	    tbx->conf.ec = le_to_i32(&meta[12]);
460	    tbx->conf.meta_char = le_to_i32(&meta[16]);
461	    tbx->conf.line_skip = le_to_i32(&meta[20]);
462	    l_nm = le_to_u32(&meta[24]);
463	    if (l_nm > l_meta - 28) goto invalid;
464	
465	    p = nm = (char*)meta + 28;
466	    // This assumes meta is NUL-terminated, so we can merrily strlen away.
467	    // hts_idx_load_local() assures this for us by adding a NUL on the end
468	    // of whatever it reads.
469	    for (; p - nm < l_nm; p += strlen(p) + 1) {
470	        if (get_tid(tbx, p, 1) < 0) {
471	            hts_log_error("%s", strerror(errno));
472	            goto fail;
473	        }
474	    }
475	    return tbx;
476	
477	 invalid:
478	    hts_log_error("Invalid index header for %s", fnidx ? fnidx : fn);
479	
480	 fail:
481	    tbx_destroy(tbx);
482	    return NULL;
483	}
