500	const char **tbx_seqnames(tbx_t *tbx, int *n)
501	{
502	    khash_t(s2i) *d = (khash_t(s2i)*)tbx->dict;
503	    if (d == NULL)
504	    {
505	        *n = 0;
506	        return calloc(1, sizeof(char *));
507	    }
508	    int tid, m = kh_size(d);
509	    const char **names = (const char**) calloc(m,sizeof(const char*));
510	    khint_t k;
511	    if (!names) {
512	        *n = 0;
513	        return NULL;
514	    }
515	    for (k=kh_begin(d); k<kh_end(d); k++)
516	    {
517	        if ( !kh_exist(d,k) ) continue;
518	        tid = kh_val(d,k);
519	        assert( tid<m );
520	        names[tid] = kh_key(d,k);
521	    }
522	    // sanity check: there should be no gaps
523	    for (tid=0; tid<m; tid++)
524	        assert(names[tid]);
525	    *n = m;
526	    return names;
527	}
